import base64
import io
import json
import os
from decimal import Decimal, InvalidOperation

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _to_float(value):
    if value is None:
        return None
    try:
        if isinstance(value, (int, float)):
            return float(value)
        return float(Decimal(str(value)))
    except (InvalidOperation, ValueError, TypeError):
        return None


def _to_str(value):
    if value is None:
        return None
    text = str(value).strip()
    return text or None


def _normalize_currency(currency_obj):
    if currency_obj is None:
        return {"amount": None, "currency": None}
    amount = getattr(currency_obj, "amount", None)
    code = getattr(currency_obj, "currency_code", None)
    return {
        "amount": _to_float(amount),
        "currency": _to_str(code),
    }


def _field_value(field):
    if field is None:
        return None
    value = getattr(field, "value", None)
    if value is not None:
        return value
    return getattr(field, "content", None)


def _get_field(fields, *names):
    for name in names:
        if name in fields:
            return fields[name]
    return None


def _extract_merchant(fields):
    merchant = _field_value(_get_field(fields, "VendorName", "MerchantName"))
    return _to_str(merchant)


def _extract_dates(fields):
    invoice_date = _field_value(_get_field(fields, "InvoiceDate", "TransactionDate"))
    due_date = _field_value(_get_field(fields, "DueDate"))
    return {
        "invoice_date": _to_str(invoice_date),
        "due_date": _to_str(due_date),
    }


def _extract_invoice_id(fields):
    return _to_str(_field_value(_get_field(fields, "InvoiceId", "ReceiptNumber")))


def _extract_tax(fields):
    tax_field = _get_field(fields, "TotalTax", "Tax")
    value = _field_value(tax_field)
    if hasattr(value, "amount") or hasattr(value, "currency_code"):
        return _normalize_currency(value)
    return {"amount": _to_float(value), "currency": None}


def _extract_totals(fields):
    total_field = _get_field(fields, "InvoiceTotal", "Total")
    subtotal_field = _get_field(fields, "SubTotal", "Subtotal")

    total_value = _field_value(total_field)
    subtotal_value = _field_value(subtotal_field)

    total = _normalize_currency(total_value) if hasattr(total_value, "amount") or hasattr(total_value, "currency_code") else {
        "amount": _to_float(total_value),
        "currency": None,
    }
    subtotal = _normalize_currency(subtotal_value) if hasattr(subtotal_value, "amount") or hasattr(subtotal_value, "currency_code") else {
        "amount": _to_float(subtotal_value),
        "currency": total.get("currency"),
    }

    if subtotal["currency"] is None:
        subtotal["currency"] = total.get("currency")

    return {"subtotal": subtotal, "total": total}


def _extract_vendor_address(fields):
    address = _field_value(_get_field(fields, "VendorAddress", "MerchantAddress", "BillingAddress"))
    if address is None:
        return None
    if hasattr(address, "content"):
        return _to_str(address.content)
    return _to_str(address)


def _extract_customer(fields):
    name = _to_str(_field_value(_get_field(fields, "CustomerName", "Customer")))
    address = _field_value(_get_field(fields, "CustomerAddress", "ShippingAddress"))
    if hasattr(address, "content"):
        address = address.content
    address = _to_str(address)
    return {
        "name": name,
        "address": address,
    }


def _extract_line_items(fields):
    items_field = _get_field(fields, "Items", "LineItems")
    if items_field is None:
        return []

    arr = getattr(items_field, "value_array", None)
    if not arr:
        value = _field_value(items_field)
        arr = getattr(value, "value_array", None) if value is not None else None
    if not arr:
        return []

    items = []
    for entry in arr:
        obj = getattr(entry, "value_object", None)
        if obj is None:
            entry_value = _field_value(entry)
            obj = getattr(entry_value, "value_object", None) if entry_value is not None else None
        if not obj:
            continue

        description = _to_str(_field_value(_get_field(obj, "Description", "ProductCode", "Name")))
        quantity = _to_float(_field_value(_get_field(obj, "Quantity")))
        unit_price_val = _field_value(_get_field(obj, "UnitPrice"))
        amount_val = _field_value(_get_field(obj, "Amount", "TotalPrice"))

        unit_price = _normalize_currency(unit_price_val) if hasattr(unit_price_val, "amount") or hasattr(unit_price_val, "currency_code") else {
            "amount": _to_float(unit_price_val),
            "currency": None,
        }
        amount = _normalize_currency(amount_val) if hasattr(amount_val, "amount") or hasattr(amount_val, "currency_code") else {
            "amount": _to_float(amount_val),
            "currency": unit_price.get("currency"),
        }

        if amount["currency"] is None:
            amount["currency"] = unit_price.get("currency")

        items.append(
            {
                "description": description,
                "quantity": quantity,
                "unit_price": unit_price,
                "amount": amount,
            }
        )
    return items


def normalize_expense_document(document_bytes, content_type="application/octet-stream"):
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(key),
    )

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        body=io.BytesIO(document_bytes),
        content_type=content_type,
    )
    result = poller.result()

    document = result.documents[0] if result.documents else None
    if document is None:
        return {
            "provider": "azure-document-intelligence",
            "model_id": "prebuilt-invoice",
            "merchant": None,
            "invoice_id": None,
            "invoice_date": None,
            "due_date": None,
            "vendor_address": None,
            "customer": {"name": None, "address": None},
            "subtotal": {"amount": None, "currency": None},
            "tax": {"amount": None, "currency": None},
            "total": {"amount": None, "currency": None},
            "line_items": [],
            "raw": {"documents": []},
        }

    fields = document.fields or {}

    totals = _extract_totals(fields)
    tax = _extract_tax(fields)
    if tax["currency"] is None:
        tax["currency"] = totals["total"].get("currency") or totals["subtotal"].get("currency")

    normalized = {
        "provider": "azure-document-intelligence",
        "model_id": "prebuilt-invoice",
        "merchant": _extract_merchant(fields),
        "invoice_id": _extract_invoice_id(fields),
        "invoice_date": _extract_dates(fields)["invoice_date"],
        "due_date": _extract_dates(fields)["due_date"],
        "vendor_address": _extract_vendor_address(fields),
        "customer": _extract_customer(fields),
        "subtotal": totals["subtotal"],
        "tax": tax,
        "total": totals["total"],
        "line_items": _extract_line_items(fields),
        "raw": {
            "document_type": getattr(document, "doc_type", None),
            "confidence": getattr(document, "confidence", None),
        },
    }

    total_currency = normalized["total"].get("currency")
    if total_currency:
        if normalized["subtotal"]["currency"] is None:
            normalized["subtotal"]["currency"] = total_currency
        if normalized["tax"]["currency"] is None:
            normalized["tax"]["currency"] = total_currency
        for item in normalized["line_items"]:
            if item["unit_price"]["currency"] is None:
                item["unit_price"]["currency"] = total_currency
            if item["amount"]["currency"] is None:
                item["amount"]["currency"] = total_currency

    return normalized


def normalize_expense_document_from_base64(document_base64, content_type="application/pdf"):
    return normalize_expense_document(base64.b64decode(document_base64), content_type=content_type)


def normalize_expense_document_to_json(document_bytes, content_type="application/octet-stream"):
    return json.dumps(normalize_expense_document(document_bytes, content_type=content_type), ensure_ascii=False)
